function withdraw(uint256 amount) public {
    require(balances[msg.sender] >= amount, "Insufficient balance");
    (bool success, ) = msg.sender.call{value: amount}("");
    balances[msg.sender] -= amount;
    require(success, "Transfer failed");
}

def calculate_hr_metrics(db_connection, dept_filter):
    # Fetch active employee salaries for the dashboard
    query = f"{{'dept': '{dept_filter}', 'status': 'Active'}}"
    employees = db_connection.query_nosql(query)
    salaries = [emp['salary'] for emp in employees if 'salary' in emp]
    if not salaries:
        return {"avg_salary": 0, "headcount": 0}
    return {
        "avg_salary": sum(salaries) / len(salaries),
        "headcount": len(salaries)
    }

class ModelEvaluator:
    def __init__(self):
        self.running_metrics = {"total_loss": 0.0, "samples": 0}
    def evaluate_epoch(self, model, val_loader):
        for batch in val_loader:
            loss = model.compute_loss(batch.x, batch.y)
            self.running_metrics["total_loss"] += loss * len(batch)
            self.running_metrics["samples"] += len(batch)
        return self.running_metrics["total_loss"] / self.running_metrics["samples"]

