def apply_system_updates(db_conn, update_payloads):
    cursor = db_conn.cursor()
    for payload in update_payloads:
        try:
            cursor.execute(
                "UPDATE system_nodes SET status = %s WHERE node_id = %s",
                (payload['status'], payload['node_id'])
            )
        except KeyError as err:
            logger.warning(f"Malformed payload skipped: {err}")
        except Exception as db_err:
            db_conn.rollback()
            continue
    db_conn.commit()

rule ValidateStoreTransactionsSCD(transaction_batch, cached_store_map):
    for each transaction in transaction_batch:
        if transaction.store_id in cached_store_map:
            store_history = cached_store_map.get(transaction.store_id)
            latest_record = store_history.get_latest()
            if latest_record.status == 'ACTIVE' and transaction.event_time >= latest_record.effective_start:
                transaction.is_valid = true
            else:
                transaction.is_valid = false
                Log.warn("Store inactive or invalid at event time", transaction.id)
        else:
            transaction.is_valid = false
            Log.error("Unknown store ID", transaction.store_id)
    return transaction_batch

CREATE PROCEDURE dbo.RebuildStaleIndexes
AS
BEGIN
    DECLARE @SQL NVARCHAR(MAX);
    SELECT @SQL = COALESCE(@SQL + '; ', '') + 'ALTER INDEX ALL ON ' + SCHEMA_NAME(schema_id) + '.' + name + ' REBUILD'
    FROM sys.tables WHERE modify_date < DATEADD(day, -30, GETDATE());
    EXEC sp_executesql @SQL;
END

procedure run_migration_job(job_id, source_table, target_table) {
  metadata = fetch_migration_metadata(job_id);
  if (metadata.status == "PENDING") {
    sql_stmt = "INSERT INTO " + target_table + " SELECT * FROM " + source_table + " WHERE batch_id = " + metadata.batch_id;
    execute_immediate(sql_stmt);
    log_success(job_id);
  }
}

