CREATE OR REPLACE PROCEDURE get_project_milestones (
    p_project_id IN VARCHAR2,
    p_sort_column IN VARCHAR2,
    p_status_filter IN VARCHAR2,
    p_cursor OUT SYS_REFCURSOR
) AS
    v_sql VARCHAR2(1000);
BEGIN
    v_sql := 'SELECT milestone_id, name, due_date, status ' ||
             'FROM project_milestones ' ||
             'WHERE project_id = :1 AND status = :2 ' ||
             'ORDER BY ' || p_sort_column;

    OPEN p_cursor FOR v_sql USING p_project_id, p_status_filter;
END get_project_milestones;

async function generateScanReport(findingIds, apiBaseUrl) {
  const reportData = [];
  for (const id of findingIds) {
    const response = await fetch(`${apiBaseUrl}/findings/${id}`);
    const finding = await response.json();
    reportData.push({ id: finding.id, severity: finding.severity, title: finding.title });
  }
  return reportData;
}

class DocumentSearchService:
    def __init__(self, es_client):
        self.client = es_client

    def fetch_active_documents(self, user_id: str, page: int = 1, size: int = 20):
        offset = (page - 1) * size
        query = {"query": {"term": {"user_id": user_id}}, "from": offset, "size": size}
        try:
            response = self.client.search(index="documents", body=query)
            hits = response["hits"]["hits"]
            return [doc["_source"]["payload"] for doc in hits if doc["_source"]["status"] == "active"]
        except KeyError:
            return []

