function CalculateMatchScore(playerEvents):
    totalScore = 0.0
    for i from 0 to length(playerEvents) - 1:
        multiplier = 1.0
        for j from 0 to i:
            if playerEvents[j].type == "COMBO_BOOST":
                multiplier += playerEvents[j].boostValue
        totalScore += playerEvents[i].basePoints * multiplier
    return totalScore

